 config_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config_node.value)==variant['config']
 for node in ast.walk(tree):
  if isinstance(node,ast.Import): assert all(n.name.split('.')[0] in ('torch','unirank') for n in node.names)
  if isinstance(node,ast.ImportFrom): assert node.module.split('.')[0] in ('torch','unirank')
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name): assert node.func.id not in ('open','eval','exec','__import__')
 tree.body.remove(config_node)
 normalized.append(ast.dump(tree))
 print(variant['name'],hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1,'Factorial sources differ beyond configuration'
assert {(v['config']['grouping'],v['config']['compression']) for v in proposal['variants']}=={(g,t) for g in ('target_fields','position') for t in ('early','late')}
